import{_ as n,a0 as s,w as i,s as l,ao as d,I as a,x as e,a1 as r,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"dupeGuru - 直接從硬盤中查找並移除重複文件 | LCTT x X-CMD","titleTemplate":false,"description":"dupeGuru - 直接從硬盤中查找並移除重複文件 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"dupeGuru - 直接從硬盤中查找並移除重複文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"dupeGuru - 直接從硬盤中查找並移除重複文件 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20141127 dupeGuru--Find And Remove Duplicate Files Instantly From Hard Drive","title":"dupeGuru - 直接從硬盤中查找並移除重複文件","tag":"201503","desc":""},"relativePath":"201503/20141127 dupeGuru--Find And Remove Duplicate Files Instantly From Hard Drive.md","filePath":"[post].md"}'),o={name:"201503/20141127 dupeGuru--Find And Remove Duplicate Files Instantly From Hard Drive.md"};function g(h,u,m,b,G,f){const t=s("Link");return i(),l("div",null,[u[20]||(u[20]=d('<h1 id="dupeguru-直接從硬盤中查找並移除重複文件" tabindex="-1">dupeGuru - 直接從硬盤中查找並移除重複文件 <a class="header-anchor" href="#dupeguru-直接從硬盤中查找並移除重複文件" aria-label="Permalink to “dupeGuru - 直接從硬盤中查找並移除重複文件”">​</a></h1><h3 id="簡介" tabindex="-1">簡介 <a class="header-anchor" href="#簡介" aria-label="Permalink to “簡介”">​</a></h3><p>對我們來説，磁盤被裝滿是棘手問題之一。無論我們如何小心謹慎，我們總可能將相同的文件複製到多個不同的地方，或者在不知情的情況下，重複下載了同一個文件。因此，遲早你會看到“磁盤已滿”的錯誤提示，若此時我們確實需要一些磁盤空間來存儲重要數據，以上情形無疑是最糟糕的。假如你確信自己的系統中有重複文件，那麼 <strong>dupeGuru</strong> 可能會幫助到你。</p><p>dupeGuru 團隊也開發了名為 <strong>dupeGuru 音樂版</strong> 的應用來移除重複的音樂文件，和名為 <strong>dupeGuru 圖片版</strong> 的應用來移除重複的圖片文件。</p><h3 id="_1-dupeguru-標準版" tabindex="-1">1. dupeGuru (標準版) <a class="header-anchor" href="#_1-dupeguru-標準版" aria-label="Permalink to “1. dupeGuru (標準版)”">​</a></h3>',5)),a("p",null,[u[1]||(u[1]=e("需要告訴那些不熟悉 ",-1)),r(t,{href:"http://www.hardcoded.net/dupeguru/"},{default:p(()=>[...u[0]||(u[0]=[e("dupeGuru",-1)])]),_:1}),u[2]||(u[2]=e(" 的人，它是一個免費、開源、跨平台的應用，其用途是在系統中查找和移除重複文件。它可以在 Linux, Windows, 和 Mac OS X 等平台下使用。通過使用一個快速的模糊匹配算法，它可以在幾分鐘內找到重複文件。同時，你還可以調整 dupeGuru 使它去精確查找特定文件類型的重複文件，以及從你想刪除的文件中，清除某種文件。它支持英語、 法語、 德語、 中文 （簡體）、 捷克語、 意大利語、亞美尼亞語、俄語、烏克蘭語、巴西語和越南語。",-1))]),u[21]||(u[21]=d(`<h4 id="在-ubuntu-14-10-14-04-13-10-13-04-12-04-中安裝-dupeguru" tabindex="-1">在 Ubuntu 14.10/14.04/13.10/13.04/12.04 中安裝 dupeGuru <a class="header-anchor" href="#在-ubuntu-14-10-14-04-13-10-13-04-12-04-中安裝-dupeguru" aria-label="Permalink to “在 Ubuntu 14.10/14.04/13.10/13.04/12.04 中安裝 dupeGuru”">​</a></h4><p>dupeGuru 開發者已經構建了一個 Ubuntu PPA (Personal Package Archives)來簡化安裝過程。想要安裝 dupeGuru，依次在終端中鍵入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-add-repository ppa:hsoft/ppa</span></span>
<span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get install dupeguru-se</span></span></code></pre></div><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3><p>使用非常簡單，可從 Unity 面板或菜單中啓動 dupeGuru。</p><p><img src="https://1102047360.rsc.cdn77.org/wp-content/uploads/2014/11/dupeGuru_007.png" alt=""></p><p>點擊位於底部的 <code>+</code> 按鈕來添加你想掃描的文件目錄。點擊 <code>掃描</code> 按鈕開始查找重複文件。</p><p><img src="https://1102047360.rsc.cdn77.org/wp-content/uploads/2014/11/dupeGuru_008.png" alt=""></p><p>一旦所選目錄中含有重複文件，那麼它將在窗口中展示重複文件。正如你所看到的，在下面的截圖中，我的下載目錄中有一個重複文件。</p><p><img src="https://1102047360.rsc.cdn77.org/wp-content/uploads/2014/11/dupeGuru-Results_009.png" alt=""></p><p>現在，你可以決定下一步如何操作。你可以刪除這個重複的文件，或者對它進行重命名，抑或是 複製/移動 到另一個位置。為此，選定該重複文件，或在菜單欄中選定寫有“<strong>僅顯示重複</strong>”選項 ，如果你選擇了“<strong>僅顯示重複</strong>”選項，則只有重複文件在窗口中可見，這樣你便可以輕鬆選擇並刪除這些文件。點擊“操作”下拉菜單，最後選擇你將執行的操作。在這裏，我只想刪除重複文件，所以我選擇了“移動標記文件到垃圾箱”這個選項。</p><p><img src="https://1102047360.rsc.cdn77.org/wp-content/uploads/2014/11/Menu_010.png" alt=""></p><p>接着，點擊“繼續”選項來移除重複文件。</p><p><img src="https://1102047360.rsc.cdn77.org/wp-content/uploads/2014/11/Deletion-Options_011.png" alt=""></p><h3 id="_2-dupeguru-音樂版" tabindex="-1">2. dupeGuru 音樂版 <a class="header-anchor" href="#_2-dupeguru-音樂版" aria-label="Permalink to “2. dupeGuru 音樂版”">​</a></h3>`,15)),a("p",null,[r(t,{href:"http://www.hardcoded.net/dupeguru_me/"},{default:p(()=>[...u[3]||(u[3]=[e("dupeGuru 音樂版",-1)])]),_:1}),u[4]||(u[4]=e(" 或簡稱 dupeGuru ME，它的功能與 dupeGuru 類似。它擁有 dupeGuru 的所有功能，但它包含更多的信息列 （如比特率，持續時間，標籤等）和更多的掃描類型（如帶有字段的文件名，標籤以及音頻內容）。和 dupeGuru 一樣，dupeGuru ME 也運行在 Linux、Windows 和 Mac OS X 中。",-1))]),u[22]||(u[22]=d('<p>它支持眾多的格式，諸如 MP3、WMA、AAC (iTunes 格式)、OGG、FLAC，以及失真率較少的 AAC 和 WMA 格式等。</p><h4 id="在-ubuntu-14-10-14-04-13-10-13-04-12-04-中安裝-dupeguru-me" tabindex="-1">在 Ubuntu 14.10/14.04/13.10/13.04/12.04 中安裝 dupeGuru ME <a class="header-anchor" href="#在-ubuntu-14-10-14-04-13-10-13-04-12-04-中安裝-dupeguru-me" aria-label="Permalink to “在 Ubuntu 14.10/14.04/13.10/13.04/12.04 中安裝 dupeGuru ME”">​</a></h4><p>現在，我們不必再添加任何 PPA，因為在前面的步驟中，我們已經進行了添加。所以在終端中鍵入以下命令來安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install dupeguru-me</span></span></code></pre></div><h3 id="使用-1" tabindex="-1">使用 <a class="header-anchor" href="#使用-1" aria-label="Permalink to “使用”">​</a></h3><p>你可以從 Unity 面板或菜單中啓動它。dupeGuru ME 的使用方法、操作界面以及外觀和正常的 dupeGuru 類似。添加你想掃描的目錄並選擇你想執行的操作。重複的音樂文件就會被刪除。</p><p><img src="https://1102047360.rsc.cdn77.org/wp-content/uploads/2014/11/dupeGuru-Music-Edition-Results_012.png" alt=""></p><h3 id="_3-dupeguru-圖片版" tabindex="-1">3. dupeGuru 圖片版 <a class="header-anchor" href="#_3-dupeguru-圖片版" aria-label="Permalink to “3. dupeGuru 圖片版”">​</a></h3>',8)),a("p",null,[r(t,{href:"http://www.hardcoded.net/dupeguru_pe/"},{default:p(()=>[...u[5]||(u[5]=[e("dupeGuru 圖片版",-1)])]),_:1}),u[6]||(u[6]=e(",或簡稱為 duepGuru PE，是一個在你的電腦中查找重複圖片的工具。它和 dupeGuru 類似，但獨具匹配重複圖片的功能。dupeGuru PE 可運行在 Linux、Windows 和 Mac OS X 中。",-1))]),u[23]||(u[23]=d('<p>dupeGuru PE 支持 JPG、PNG、TIFF、GIF 和 BMP 等圖片格式。所有的這些格式可以被同時比較。Mac OS X 版的 dupeGuru PE 還支持 PSD 和 RAW (CR2 和 NEF) 格式。</p><h4 id="在-ubuntu-14-10-14-04-13-10-13-04-12-04-中安裝-dupeguru-pe" tabindex="-1">在 Ubuntu 14.10/14.04/13.10/13.04/12.04 中安裝 dupeGuru PE <a class="header-anchor" href="#在-ubuntu-14-10-14-04-13-10-13-04-12-04-中安裝-dupeguru-pe" aria-label="Permalink to “在 Ubuntu 14.10/14.04/13.10/13.04/12.04 中安裝 dupeGuru PE”">​</a></h4><p>由於我們已經添加了 PPA，我們也不必為 dupeGuru PE 再次添加。只需運行如下命令來安裝它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install dupeguru-pe</span></span></code></pre></div><h4 id="使用-2" tabindex="-1">使用 <a class="header-anchor" href="#使用-2" aria-label="Permalink to “使用”">​</a></h4><p>就使用方法，操作界面和外觀而言，它與 dupeGuru，dupeGuru ME 類似。我就納悶為什麼開發者為不同的類別開發了不同的版本。我想如果開發一個結合以上三個版本功能的應用，或許會更好。</p><p>啓動它，添加你想掃描的目錄，並選擇你想執行的操作。就這樣，你的重複文件將被清除。</p><p><img src="https://1102047360.rsc.cdn77.org/wp-content/uploads/2014/11/dupeGuru-Picture-Edition-Results_014.png" alt=""></p><p>如果因為任何的安全問題而不能移除某些重複文件，請記下這些文件的位置，通過終端或文件管理器來手動刪除它們。</p><p>歡呼吧！</p><hr>',11)),a("p",null,[u[8]||(u[8]=e("via: ",-1)),r(t,{href:"http://www.unixmen.com/dupeguru-find-remove-duplicate-files-instantly-hard-drive/"},{default:p(()=>[...u[7]||(u[7]=[e("http://www.unixmen.com/dupeguru-find-remove-duplicate-files-instantly-hard-drive/",-1)])]),_:1})]),a("p",null,[u[12]||(u[12]=e("作者：",-1)),r(t,{href:"http://www.unixmen.com/author/sk/"},{default:p(()=>[...u[9]||(u[9]=[e("SK",-1)])]),_:1}),u[13]||(u[13]=e(" 譯者：",-1)),r(t,{href:"https://github.com/FSSlc"},{default:p(()=>[...u[10]||(u[10]=[e("FSSlc",-1)])]),_:1}),u[14]||(u[14]=e(" 校對：",-1)),r(t,{href:"https://github.com/carolinewuyan"},{default:p(()=>[...u[11]||(u[11]=[e("Caroline",-1)])]),_:1})]),a("p",null,[u[17]||(u[17]=e("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...u[15]||(u[15]=[e("LCTT",-1)])]),_:1}),u[18]||(u[18]=e(" 原創翻譯，",-1)),r(t,{href:"http://linux.cn/"},{default:p(()=>[...u[16]||(u[16]=[e("Linux中國",-1)])]),_:1}),u[19]||(u[19]=e(" 榮譽推出",-1))])])}const T=n(o,[["render",g]]);export{P as __pageData,T as default};
